async function logAdminAction(action: string, targetType: string, targetId?: string, details: Record<string, unknown> = {}, result: 'success' | 'failure' = 'success') {
  try {
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return false
    const { error } = await supabase.from('portfolio_admin_audit_log').insert({ actor_id: user.id, action, target_type: targetType, target_id: targetId ?? null, details, result })
    return !error
  } catch {
    return false
  }
}

const participantSchema = z.object({ full_name: z.string().max(120), email: z.union([z.string().email(), z.literal('')]), enrollment: z.string().max(80), professional_area: z.string().max(120), photo_path: z.union([z.string().url(), z.literal('')]), bio: z.string().max(800), participation_status: z.enum(['active','paused','completed']) })
const courseSchema = z.object({ title: z.string().min(2).max(180), description: z.string().max(800), status: z.enum(['pending','in_progress','review','completed']), course_code: z.string().max(40), prerequisite: z.string().max(180), facilitator: z.string().max(180), credits: z.string().regex(/^(?:\d+(?:\.\d{1,2})?)?$/, 'Usa un número válido.'), hours_theoretical: z.string().regex(/^\d*$/, 'Usa un número entero.'), hours_practical: z.string().regex(/^\d*$/, 'Usa un número entero.'), hours_research_virtual: z.string().regex(/^\d*$/, 'Usa un número entero.'), hours_independent: z.string().regex(/^\d*$/, 'Usa un número entero.') })
const experienceSchema = z.object({ participant_id: z.string().uuid(), course_id: z.string().uuid(), title: z.string().min(3).max(180), description: z.string().min(5).max(6000), learning_date: z.string() })
const reflectionSchema = z.object({ participant_id: z.string().uuid(), course_id: z.string(), title: z.string().min(3).max(180), body: z.string().min(10).max(5000), reflection_type: z.enum(['individual','group']) })

function FieldError({ children }: { children?: string }) { return children ? <p className="mt-1 text-xs text-red-700">{children}</p> : null }
function SectionTitle({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="flex flex-wrap items-end justify-between gap-4"><div><p className="eyebrow">{eyebrow}</p><h2 className="mt-2 text-2xl font-bold tracking-tight text-[#0B2545]">{title}</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{description}</p></div>{action}</div> }

function AuthGate() {
  const { mutate } = useSWRConfig()
  const { data: user, isLoading: checking } = useSWR('portfolio-auth', async () => {
    const { data, error } = await supabase.auth.getUser()
    if (error) throw error
    return data.user ? { id: data.user.id, email: data.user.email } : null
  })

  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange(() => {
      queueMicrotask(() => void mutate('portfolio-auth'))
    })
    return () => subscription.unsubscribe()
  }, [mutate])

  const { data: isAdmin, isLoading: roleLoading } = useSWR(user?.id ? ['portfolio-admin-role', user.id] : null, async ([, userId]) => {
    const { data, error } = await supabase.from('portfolio_admins').select('user_id').eq('user_id', userId).maybeSingle()
    return !error && !!data
  })
  const { data: participant, isLoading: participantLoading } = useSWR(user && isAdmin === false ? ['portfolio-current-participant', user.id] : null, async () => {
    const { data, error } = await supabase.rpc('portfolio_current_participant')
    if (error) throw error
    return Array.isArray(data) ? data[0] || null : data
  })

  if (checking) return <main className="grid min-h-screen place-items-center bg-slate-50"><Skeleton className="h-64 w-full max-w-md rounded-2xl" /></main>
  if (!user) return <AdminAuth />
  if (roleLoading || isAdmin === undefined || (isAdmin === false && participantLoading)) return <main className="grid min-h-screen place-items-center bg-slate-50"><Skeleton className="h-64 w-full max-w-md rounded-2xl" /></main>
  if (!isAdmin && participant) return <ParticipantWorkspace profile={participant} />
  if (!isAdmin) return <main className="flex min-h-screen items-center justify-center bg-slate-50 px-5"><Card className="w-full max-w-lg"><CardContent className="p-8 text-center"><span className="mx-auto grid size-14 place-items-center rounded-2xl bg-amber-50 text-amber-700"><CircleHelp /></span><h1 className="mt-5 text-xl font-bold text-[#0B2545]">Acceso pendiente de autorización</h1><p className="mt-3 text-sm leading-6 text-slate-600">La cuenta {user.email} aún no está vinculada a un perfil del equipo ni tiene permisos de administración. Confirma tu correo y pide que el administrador registre ese mismo correo en tu perfil.</p><div className="mt-6 flex justify-center gap-3"><Button variant="outline" onClick={() => void supabase.auth.signOut().then(() => window.location.assign('/admin'))}>Cerrar sesión</Button><Button onClick={() => window.location.assign('/')}>Volver al portafolio</Button></div></CardContent></Card></main>
  return <AdminDashboard userEmail={user.email || ''} />
}

export function AdminConsole() { return <AuthGate /> }

function AdminDashboard({ userEmail }: { userEmail: string }) {
  const [activeTab, setActiveTab] = useState('resumen')
  const [directEditMode, setDirectEditMode] = useState(false)
  const { data, error, isLoading, mutate } = useSWR('portfolio-admin-data', async () => {
    const [participantResult, courseResult, experienceResult, evidenceResult, relationResult, reflectionResult, settingResult, auditResult] = await Promise.all([
      supabase.rpc('portfolio_admin_participants'),
      supabase.from('portfolio_courses').select('*').order('trimester').order('course_number'),
      supabase.from('portfolio_experiences').select('*').order('created_at', { ascending: false }),
      supabase.from('portfolio_evidence').select('*').order('created_at', { ascending: false }),
      supabase.from('portfolio_experience_participants').select('experience_id,participant_id'),
      supabase.from('portfolio_reflections').select('*').order('created_at', { ascending: false }),
      supabase.from('portfolio_settings').select('*'),
      supabase.from('portfolio_admin_audit_log').select('id,actor_id,action,target_type,target_id,details,result,created_at').order('created_at', { ascending: false }).limit(40),
    ])
    const firstError = participantResult.error || courseResult.error || experienceResult.error || evidenceResult.error || relationResult.error || reflectionResult.error || settingResult.error || auditResult.error
    if (firstError) throw firstError
    return {
      participants: (participantResult.data || []) as Participant[],
      courses: (courseResult.data || []) as Course[],
      experiences: ((experienceResult.data || []) as Experience[]).map((experience) => ({ ...experience, participants: (relationResult.data || []).filter((relation) => relation.experience_id === experience.id).map((relation) => relation.participant_id) })),
      evidence: (evidenceResult.data || []) as Evidence[],
      reflections: (reflectionResult.data || []) as Reflection[],
      settings: (settingResult.data || []) as Array<{ key: string; value: Record<string, string>; publication_status?: 'draft' | 'review' | 'published'; updated_at?: string }>,
      audit: (auditResult.data || []) as Array<{ id: string; actor_id: string; action: string; target_type: string; target_id: string | null; details: Record<string, unknown>; result: 'success' | 'failure'; created_at: string }>,
    }
  })
  const refresh = () => mutate()
  const publishedCount = data?.experiences.filter((item) => item.status === 'published').length || 0
  const completedCourses = data?.courses.filter((item) => item.status === 'completed').length || 0
  const chartData = useMemo(() => [1,2,3,4].map((term) => ({ name: `T${term}`, total: data?.courses.filter((course) => course.trimester === term && course.status === 'completed').length || 0 })), [data?.courses])

  async function signOut() { await supabase.auth.signOut(); window.location.assign('/admin') }
  async function deleteRecord(table: 'portfolio_experiences' | 'portfolio_evidence' | 'portfolio_reflections', id: string) {
    if (!window.confirm('¿Eliminar este registro? Esta acción no se puede deshacer.')) return
    const { error } = await supabase.from(table).delete().eq('id', id)
    if (error) {
      await logAdminAction('delete_record', table, id, {}, 'failure')
      toast.error('No se pudo eliminar. Revisa los permisos e inténtalo de nuevo.')
    } else {
      toast.success('Registro eliminado.')
      if (!await logAdminAction('delete_record', table, id)) toast.warning('El registro se eliminó, pero no se pudo registrar la auditoría.')
      await refresh()
    }
  }

  if (isLoading) return <main className="min-h-screen bg-[#F8FAFC] p-6"><div className="mx-auto grid max-w-7xl gap-5 md:grid-cols-[240px_1fr]"><Skeleton className="h-[42rem] rounded-2xl" /><Skeleton className="h-[42rem] rounded-2xl" /></div></main>
  if (error || !data) return <main className="grid min-h-screen place-items-center bg-slate-50 p-5"><Card className="max-w-lg"><CardContent className="p-8"><h1 className="text-xl font-bold">No se pudieron cargar los datos</h1><p className="mt-3 text-sm leading-6 text-slate-600">Confirma que la migración de base de datos se haya completado y que tu cuenta tenga permisos de administración.</p><Button className="mt-5" onClick={() => refresh()}>Reintentar</Button></CardContent></Card></main>

  return <div className="min-h-screen bg-[#F4F7FB] text-slate-800 md:flex">
    <aside className="flex w-full flex-col bg-[#0B2545] text-white md:fixed md:inset-y-0 md:w-[250px]">
      <div className="flex items-center justify-between border-b border-white/10 px-5 py-5 md:justify-start md:px-6"><Link href="/" className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-white/10"><GraduationCap /></span><span className="leading-tight"><b className="block text-sm">PORTAFOLIO UAPA</b><span className="text-xs text-blue-100/65">Administración</span></span></Link><button className="text-xs text-blue-100 md:hidden" onClick={signOut}>Salir</button></div>
      <nav className="flex gap-1 overflow-x-auto p-3 md:flex-1 md:flex-col md:overflow-visible md:p-4" aria-label="Secciones de administración">{tabs.map(({ id, label, icon: Icon }) => <button key={id} type="button" onClick={() => setActiveTab(id)} aria-current={activeTab === id ? 'page' : undefined} className={`flex shrink-0 items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm transition md:w-full ${activeTab === id ? 'bg-white/12 font-semibold text-white' : 'text-blue-100/70 hover:bg-white/5 hover:text-white'}`}><Icon size={18} />{label}{activeTab === id && <ChevronRight size={15} className="ml-auto hidden md:block" />}</button>)}</nav>
      <div className="hidden border-t border-white/10 p-4 md:block"><div className="truncate text-xs text-blue-100/65">Sesión</div><div className="mt-1 truncate text-sm">{userEmail}</div><Button variant="ghost" className="mt-3 w-full justify-start text-blue-100 hover:text-white" onClick={signOut}><LogOut data-icon="inline-start" />Cerrar sesión</Button></div>
    </aside>

    <main className="min-w-0 flex-1 px-5 py-7 md:ml-[250px] md:px-9 md:py-9 lg:px-12">
      <div className="mx-auto max-w-6xl"><div className="mb-8 flex flex-wrap items-center justify-between gap-4"><div><Link href="/" className="inline-flex items-center gap-1.5 text-xs font-medium text-slate-500 hover:text-blue-800"><ArrowLeft size={14} />Ver portafolio público</Link><h1 className="mt-3 text-2xl font-bold tracking-tight text-[#0B2545] sm:text-3xl">{tabs.find((tab) => tab.id === activeTab)?.label}</h1></div><div className="flex items-center gap-3"><Button type="button" variant={directEditMode ? 'default' : 'outline'} aria-pressed={directEditMode} onClick={() => setDirectEditMode((enabled) => !enabled)}><Pencil data-icon="inline-start" />Modo Edición Directa {directEditMode ? 'activado' : 'desactivado'}</Button><Link href="/" title="Guarda cada formulario para conservar sus cambios antes de volver" className="inline-flex h-9 items-center gap-2 rounded-lg border border-slate-300 bg-white px-3 text-sm font-medium text-slate-800 shadow-xs transition hover:bg-slate-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-700"><Save size={16} />Guardar y volver al sitio</Link><span className="hidden items-center gap-2 rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1.5 text-xs font-medium text-emerald-800 sm:flex"><ShieldCheck size={14} />Espacio privado</span></div></div>
        {directEditMode && <DirectPublicationPanel participants={data.participants} courses={data.courses} experiences={data.experiences} evidence={data.evidence} reflections={data.reflections} settings={data.settings} onChanged={refresh} />}
        {activeTab === 'resumen' && <section className="space-y-7"><SectionTitle eyebrow="Vista general" title="El portafolio, de un vistazo." description="Estado de la ruta formativa, sus aportes y la revisión de contenidos." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{ label: 'Participantes', value: data.participants.length, note: 'perfiles del equipo', icon: Users }, { label: 'Asignaturas', value: data.courses.length, note: 'en cuatro trimestres', icon: BookOpen }, { label: 'Completadas', value: completedCourses, note: 'asignaturas cerradas', icon: Check }, { label: 'Publicadas', value: publishedCount, note: 'experiencias visibles', icon: FileText }].map(({label,value,note,icon:Icon}) => <Card key={label} className="border-slate-200/80 shadow-sm"><CardContent className="flex items-center gap-4 p-5"><span className="grid size-11 place-items-center rounded-xl bg-blue-50 text-blue-800"><Icon size={19} /></span><div><p className="text-2xl font-bold text-[#0B2545]">{value}</p><p className="text-sm font-medium">{label}</p><p className="text-xs text-slate-500">{note}</p></div></CardContent></Card>)}</div><div className="grid gap-4 lg:grid-cols-[1.3fr_0.7fr]"><Card className="border-slate-200/80 shadow-sm"><CardContent className="p-6"><div className="flex items-start justify-between"><div><h3 className="font-semibold text-[#0B2545]">Avance por trimestre</h3><p className="mt-1 text-sm text-slate-500">Asignaturas marcadas como completadas</p></div><BookOpen size={18} className="text-blue-700" /></div><div className="mt-5 h-64"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData} margin={{ top: 10, right: 12, left: -22, bottom: 0 }}><defs><linearGradient id="courseFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#0B2545" stopOpacity={0.22} /><stop offset="95%" stopColor="#0B2545" stopOpacity={0.02} /></linearGradient></defs><CartesianGrid stroke="#E8EEF5" vertical={false} /><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#64748B', fontSize: 12 }} /><YAxis allowDecimals={false} axisLine={false} tickLine={false} tick={{ fill: '#94A3B8', fontSize: 12 }} /><Tooltip /><Area type="monotone" dataKey="total" name="Completadas" stroke="#0B2545" strokeWidth={2.5} fill="url(#courseFill)" /></AreaChart></ResponsiveContainer></div></CardContent></Card><Card className="border-slate-200/80 shadow-sm"><CardContent className="p-6"><h3 className="font-semibold text-[#0B2545]">Pendientes de publicar</h3><p className="mt-1 text-sm text-slate-500">Contenidos del equipo en preparación</p><div className="mt-5 space-y-4">{[{label:'Experiencias en revisión',value:data.experiences.filter((row)=>row.status==='review').length},{label:'Reflexiones en revisión',value:data.reflections.filter((row)=>row.status==='review').length},{label:'Evidencias adjuntas',value:data.evidence.length}].map((row)=><div key={row.label} className="flex items-center justify-between border-b border-slate-100 pb-3 last:border-0"><span className="text-sm text-slate-600">{row.label}</span><Badge variant="secondary">{row.value}</Badge></div>)}</div><Button variant="outline" className="mt-3 w-full" onClick={()=>setActiveTab('experiencias')}>Revisar contenido <ChevronRight data-icon="inline-end" /></Button></CardContent></Card></div></section>}

        {activeTab === 'participantes' && <section className="space-y-7"><SectionTitle eyebrow="Gestión del equipo" title="Perfiles y vinculación de cuentas." description="Completa la información de cada participante. El correo institucional enlaza automáticamente la cuenta cuando su propietario confirma el registro." /><div className="grid gap-4 lg:grid-cols-2">{data.participants.map((participant)=><ParticipantEditor key={participant.id} participant={participant} onSave={async (values)=>{const parsed=participantSchema.safeParse(values); if(!parsed.success){toast.error('Revisa los campos del perfil.');return} let updateQuery=supabase.from('portfolio_participants').update({...parsed.data,email:parsed.data.email||null,photo_path:parsed.data.photo_path||null}).eq('id',participant.id);if(participant.updated_at)updateQuery=updateQuery.eq('updated_at',participant.updated_at);const {data:saved,error}=await updateQuery.select('id').maybeSingle();if(error){await logAdminAction('update_participant','participant',participant.id,{},'failure');toast.error('No se pudo actualizar el perfil. El borrador sigue en el formulario.');return}if(!saved){await logAdminAction('update_participant','participant',participant.id,{reason:'stale_record'},'failure');toast.error('El perfil cambió en otra sesión. No se sobrescribieron los cambios; revisa la versión actualizada.');await refresh();return}toast.success('Perfil actualizado.');if(!await logAdminAction('update_participant','participant',participant.id,{code:participant.code}))toast.warning('El perfil se guardó, pero no se pudo registrar la auditoría.');await refresh()}} />)}</div><Card className="border-blue-100 bg-blue-50/60"><CardContent className="flex items-start gap-3 p-5"><CircleHelp className="mt-0.5 shrink-0 text-blue-700" size={18} /><p className="text-sm leading-6 text-blue-950"><strong>Vinculación segura.</strong> Registra aquí el correo del participante. Cuando se inscriba y confirme ese mismo correo, la cuenta quedará vinculada al perfil automáticamente. Los datos de matrícula y contacto solo los ven administradores.</p></CardContent></Card></section>}

        {activeTab === 'pensum' && <section className="space-y-7"><SectionTitle eyebrow="Ruta curricular" title="Asignaturas y avance." description="Administra las asignaturas, los datos oficiales y los totales declarados del programa y cada trimestre." /><CurriculumTotalsEditor courses={data.courses} value={data.settings.find((setting)=>setting.key==='curriculum')?.value||{}} onSave={async(value)=>{const {error}=await supabase.from('portfolio_settings').upsert({key:'curriculum',value});if(error){await logAdminAction('update_curriculum_totals','settings','curriculum',{},'failure');toast.error('No se pudieron guardar los totales.');return}toast.success('Totales curriculares guardados.');if(!await logAdminAction('update_curriculum_totals','settings','curriculum'))toast.warning('Los totales se guardaron, pero no se pudo registrar la auditoría.');await refresh()}} /><div className="grid gap-4 lg:grid-cols-2">{data.courses.map((course)=><CourseEditor key={course.id} course={course} onSave={async (values)=>{const parsed=courseSchema.safeParse(values);if(!parsed.success){toast.error('Revisa los datos de la asignatura.');return}const {credits,hours_theoretical,hours_practical,hours_research_virtual,hours_independent,...courseValues}=parsed.data;const title=courseValues.title.trim();const isPlaceholder=course.is_placeholder&&title===course.title;const toNumber=(value:string)=>value===''?null:Number(value);let updateQuery=supabase.from('portfolio_courses').update({...courseValues,course_code:courseValues.course_code.trim()||null,credits:toNumber(credits),hours_theoretical:toNumber(hours_theoretical),hours_practical:toNumber(hours_practical),hours_research_virtual:toNumber(hours_research_virtual),hours_independent:toNumber(hours_independent),is_placeholder:isPlaceholder}).eq('id',course.id);if(course.updated_at)updateQuery=updateQuery.eq('updated_at',course.updated_at);const {data:saved,error}=await updateQuery.select('id').maybeSingle();if(error){await logAdminAction('update_course','course',course.id,{},'failure');toast.error('No se pudo guardar la asignatura. El borrador sigue en el formulario.');return}if(!saved){await logAdminAction('update_course','course',course.id,{reason:'stale_record'},'failure');toast.error('La asignatura cambió en otra sesión. No se sobrescribieron los cambios; revisa la versión actualizada.');await refresh();return}toast.success('Asignatura actualizada.');if(!await logAdminAction('update_course','course',course.id,{course_code:course.course_code}))toast.warning('La asignatura se guardó, pero no se pudo registrar la auditoría.');await refresh()}} />)}</div></section>}

        {activeTab === 'experiencias' && <section className="space-y-7"><SectionTitle eyebrow="Producciones académicas" title="Experiencias y evidencias." description="Registra aprendizajes por asignatura, vincula a las personas participantes y administra evidencias desde almacenamiento privado." /><LearningRecordsManager participants={data.participants} courses={data.courses} experiences={data.experiences} evidence={data.evidence} onChanged={refresh} onAudit={logAdminAction} /></section>}

        {activeTab === 'reflexiones' && <section className="space-y-7"><SectionTitle eyebrow="Pensamiento crítico" title="Reflexiones individuales y grupales." description="Registra aportes del equipo. La reflexión final compartida se muestra en el portafolio cuando se publica." /><ReflectionForm participants={data.participants} courses={data.courses} onCreated={refresh} /><div className="space-y-3">{data.reflections.length===0&&<EmptyCard text="Aún no hay reflexiones registradas." />}{data.reflections.map((reflection)=><ReflectionRow key={reflection.id} reflection={reflection} participant={data.participants.find((item)=>item.id===reflection.participant_id)} course={data.courses.find((item)=>item.id===reflection.course_id)} onStatus={async(status)=>{const {error}=await supabase.from('portfolio_reflections').update({status}).eq('id',reflection.id);if(error){await logAdminAction('update_reflection_status','portfolio_reflections',reflection.id,{status},'failure');toast.error('No se pudo actualizar la reflexión.')}else{const audited=await logAdminAction('update_reflection_status','portfolio_reflections',reflection.id,{status});if(!audited)toast.warning('La reflexión se actualizó, pero no se pudo registrar la auditoría.');toast.success('Reflexión actualizada.');await refresh()}}} onDelete={()=>deleteRecord('portfolio_reflections',reflection.id)} />)}</div><AdminAcademicReflections participants={data.participants} courses={data.courses}/></section>}

        {activeTab === 'respaldo' && <section className="space-y-7"><SectionTitle eyebrow="Control y continuidad" title="Respaldo y datos institucionales." description="Descarga una copia de seguridad con los datos del portafolio o restaura un archivo exportado previamente. La restauración combina registros; no elimina datos existentes." /><SettingsEditor settings={data.settings} onSave={async(value)=>{const {error}=await supabase.from('portfolio_settings').upsert({key:'institution',value});if(error){await logAdminAction('update_institution_settings','settings','institution',{},'failure');toast.error('No se pudieron guardar los ajustes.');return}toast.success('Datos institucionales guardados.');if(!await logAdminAction('update_institution_settings','settings','institution',{fields:Object.keys(value)}))toast.warning('Los datos se guardaron, pero no se pudo registrar la auditoría.');await refresh()}} /><BackupPanel data={data} onRestored={refresh} /></section>}
        {activeTab === 'actividad' && <section className="space-y-7"><SectionTitle eyebrow="Trazabilidad" title="Actividad administrativa." description="Registro reciente de operaciones administrativas y cambios de contenido. Los eventos son de solo anexado y se limitan a las últimas 40 entradas." /><Card className="border-slate-200/80 shadow-sm"><CardContent className="p-0"><div className="divide-y divide-slate-100">{data.audit.length===0?<p className="p-6 text-sm text-slate-500">Aún no hay actividad registrada.</p>:data.audit.map((entry:{id:string;actor_id:string;action:string;target_type:string;target_id:string|null;created_at:string})=><div key={entry.id} className="flex flex-col gap-1 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium text-[#0B2545]">{entry.action.replaceAll('_',' ')}</p><p className="text-xs text-slate-500">{entry.target_type}{entry.target_id?` · ${entry.target_id}`:''} · admin {entry.actor_id.slice(0,8)}</p></div><div className="flex items-center gap-3"><Badge variant={'result' in entry && entry.result === 'failure' ? 'destructive' : 'secondary'}>{'result' in entry && entry.result === 'failure' ? 'Fallido' : 'Correcto'}</Badge><time className="text-xs text-slate-500" dateTime={entry.created_at}>{new Date(entry.created_at).toLocaleString('es-DO')}</time></div></div>)}</div></CardContent></Card></section>}
      </div>
    </main>
  </div>
}

function DirectPublicationPanel({ participants, courses, experiences, evidence, reflections, settings, onChanged }: { participants: Participant[]; courses: Course[]; experiences: Experience[]; evidence: Evidence[]; reflections: Reflection[]; settings: Array<{ key: string; value: Record<string, string>; publication_status?: 'draft' | 'review' | 'published'; updated_at?: string }>; onChanged: () => Promise<unknown> }) {
  type Status = 'draft' | 'review' | 'published'
  const entries = [
    ...participants.map((item) => ({ id: item.id, label: `Participante ${item.code} · ${item.full_name || 'Perfil pendiente'}`, table: 'portfolio_participants', updatedAt: item.updated_at, status: item.publication_status ?? 'published', statusColumn: 'publication_status' })),
    ...courses.map((item) => ({ id: item.id, label: `Asignatura · ${item.title}`, table: 'portfolio_courses', updatedAt: item.updated_at, status: item.publication_status ?? 'published', statusColumn: 'publication_status' })),
    ...experiences.map((item) => ({ id: item.id, label: `Experiencia · ${item.title}`, table: 'portfolio_experiences', updatedAt: item.updated_at, status: item.status, statusColumn: 'status' })),
    ...evidence.map((item) => ({ id: item.id, label: `Evidencia · ${item.title}`, table: 'portfolio_evidence', updatedAt: item.updated_at, status: item.status, statusColumn: 'status' })),
    ...reflections.map((item) => ({ id: item.id, label: `Reflexión · ${item.title}`, table: 'portfolio_reflections', updatedAt: item.updated_at, status: item.status, statusColumn: 'status' })),
    ...settings.map((item) => ({ id: item.key, label: `Ajustes · ${item.key}`, table: 'portfolio_settings', updatedAt: item.updated_at, status: item.publication_status ?? 'published', statusColumn: 'publication_status' })),
  ]
  const [savingId, setSavingId] = useState<string | null>(null)

  async function saveStatus(item: (typeof entries)[number], status: Status) {
    if (item.status === status) return
    setSavingId(item.id)
    try {
      let query = supabase.from(item.table).update({ [item.statusColumn]: status }).eq(item.table === 'portfolio_settings' ? 'key' : 'id', item.id)
      if (item.updatedAt) query = query.eq('updated_at', item.updatedAt)
      const { data: saved, error } = await query.select(item.table === 'portfolio_settings' ? 'key' : 'id').maybeSingle()
      if (error) throw error
      if (!saved) {
        await logAdminAction('update_publication_status', item.table, item.id, { status, reason: 'stale_record' }, 'failure')
        toast.error('Este contenido cambió desde que lo abriste. Tus datos siguen intactos; actualiza la vista y revisa la versión más reciente.')
        await onChanged()
        return
      }
      const audited = await logAdminAction('update_publication_status', item.table, item.id, { status })
      toast.success(`Estado actualizado: ${status === 'draft' ? 'Borrador' : status === 'review' ? 'En revisión' : 'Publicado'}.`)
      if (!audited) toast.warning('El estado se guardó, pero no se pudo registrar la auditoría.')
      await onChanged()
    } catch {
      await logAdminAction('update_publication_status', item.table, item.id, { status }, 'failure')
      toast.error('No se pudo guardar el cambio. La conexión puede haber fallado; vuelve a intentarlo sin cerrar el formulario.')
    } finally {
      setSavingId(null)
    }
  }

  return <Card className="border-blue-200 bg-blue-50/50 shadow-sm"><CardContent className="p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-semibold text-[#0B2545]">Modo Edición Directa</h2><p className="mt-1 max-w-3xl text-sm leading-6 text-slate-600">Cambia la publicación desde aquí. Los cambios se sincronizan con Supabase; si otra persona modificó el registro, se avisará antes de aplicar una versión obsoleta.</p></div><Badge variant="secondary">{entries.length} contenidos</Badge></div><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{entries.map((item) => <label key={`${item.table}-${item.id}`} className="flex min-w-0 items-center justify-between gap-3 rounded-xl border border-slate-200 bg-white p-3"><span className="min-w-0 truncate text-sm font-medium text-slate-700">{item.label}</span><select aria-label={`Estado de publicación: ${item.label}`} disabled={savingId === item.id} value={item.status} onChange={(event) => void saveStatus(item, event.target.value as Status)} className="h-9 shrink-0 rounded-lg border border-slate-300 bg-white px-2 text-xs font-medium"><option value="draft">Borrador</option><option value="review">En revisión</option><option value="published">Publicado</option></select></label>)}</div></CardContent></Card>
}

function ParticipantEditor({participant,onSave}:{participant:Participant;onSave:(values:z.infer<typeof participantSchema>)=>Promise<void>}){
 const [saving,setSaving]=useState(false);const form=useForm<z.infer<typeof participantSchema>>({resolver:zodResolver(participantSchema),defaultValues:{full_name:participant.full_name||'',email:participant.email||'',enrollment:participant.enrollment||'',professional_area:participant.professional_area||'',photo_path:participant.photo_path||'',bio:participant.bio||'',participation_status:participant.participation_status}})
 return <Card className="border-slate-200/80 shadow-sm"><CardContent className="p-5"><div className="mb-5 flex items-center gap-3"><span className="grid size-11 place-items-center rounded-xl bg-blue-50 font-bold text-blue-900">{participant.code}</span><div><h3 className="font-semibold">{participant.full_name||'Perfil sin completar'}</h3><p className="text-xs text-slate-500">{participant.user_id?'Cuenta vinculada':'Cuenta aún no vinculada'}</p></div></div><form className="grid gap-4 sm:grid-cols-2" onSubmit={form.handleSubmit(async(values)=>{setSaving(true);await onSave(values);setSaving(false)})}><div className="space-y-1.5"><Label htmlFor={`name-${participant.id}`}>Nombre completo</Label><Input id={`name-${participant.id}`} {...form.register('full_name')} /><FieldError>{form.formState.errors.full_name?.message}</FieldError></div><div className="space-y-1.5"><Label htmlFor={`email-${participant.id}`}>Correo para vincular</Label><Input id={`email-${participant.id}`} type="email" {...form.register('email')} /><FieldError>{form.formState.errors.email?.message}</FieldError></div><div className="space-y-1.5"><Label htmlFor={`enroll-${participant.id}`}>Matrícula (privada)</Label><Input id={`enroll-${participant.id}`} {...form.register('enrollment')} /></div><div className="space-y-1.5"><Label htmlFor={`area-${participant.id}`}>Área profesional</Label><Input id={`area-${participant.id}`} {...form.register('professional_area')} /></div><div className="space-y-1.5 sm:col-span-2"><Label htmlFor={`photo-${participant.id}`}>URL de foto pública</Label><Input id={`photo-${participant.id}`} type="url" placeholder="https://…" {...form.register('photo_path')} /></div><div className="space-y-1.5 sm:col-span-2"><Label htmlFor={`bio-${participant.id}`}>Biografía</Label><textarea id={`bio-${participant.id}`} {...form.register('bio')} className="min-h-20 w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-blue-500" /></div><div className="space-y-1.5"><Label htmlFor={`status-${participant.id}`}>Estado</Label><select id={`status-${participant.id}`} {...form.register('participation_status')} className="h-9 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm"><option value="active">Activo</option><option value="paused">En pausa</option><option value="completed">Completado</option></select></div><div className="flex items-end justify-end"><Button type="submit" disabled={saving} size="sm"><Save data-icon="inline-start" />{saving?'Guardando…':'Guardar perfil'}</Button></div></form></CardContent></Card>
}

function CourseEditor({course,onSave}:{course:Course;onSave:(values:z.infer<typeof courseSchema>)=>Promise<void>}){
 const form=useForm<z.infer<typeof courseSchema>>({resolver:zodResolver(courseSchema),defaultValues:{title:course.title,description:course.description||'',status:course.status,course_code:course.course_code||'',credits:course.credits==null?'':String(course.credits),hours_theoretical:course.hours_theoretical==null?'':String(course.hours_theoretical),hours_practical:course.hours_practical==null?'':String(course.hours_practical),hours_research_virtual:course.hours_research_virtual==null?'':String(course.hours_research_virtual),hours_independent:course.hours_independent==null?'':String(course.hours_independent),prerequisite:course.prerequisite||'',facilitator:course.facilitator||''}});const [saving,setSaving]=useState(false)
 return <Card className="border-slate-200/80 shadow-sm"><CardContent className="p-5"><div className="mb-4 flex items-center justify-between"><Badge variant="secondary">Trimestre {course.trimester}</Badge><span className="text-xs text-slate-500">Asignatura {String(course.course_number).padStart(2,'0')}</span></div>{course.is_placeholder&&<p className="mb-3 text-xs font-medium text-amber-800">Título pendiente de confirmar con el pénsum oficial</p>}<form className="flex flex-col gap-4" onSubmit={form.handleSubmit(async(values)=>{setSaving(true);await onSave(values);setSaving(false)})}><div className="grid gap-4 sm:grid-cols-2"><div className="flex flex-col gap-1.5"><Label htmlFor={`course-${course.id}`}>Título oficial / marcador</Label><Input id={`course-${course.id}`} {...form.register('title')} /><FieldError>{form.formState.errors.title?.message}</FieldError></div><div className="flex flex-col gap-1.5"><Label htmlFor={`course-code-${course.id}`}>Código oficial</Label><Input id={`course-code-${course.id}`} {...form.register('course_code')} placeholder="Por confirmar" /></div><div className="flex flex-col gap-1.5"><Label htmlFor={`course-credits-${course.id}`}>Créditos</Label><Input id={`course-credits-${course.id}`} inputMode="decimal" {...form.register('credits')} /><FieldError>{form.formState.errors.credits?.message}</FieldError></div><div className="flex flex-col gap-1.5"><Label htmlFor={`course-desc-${course.id}`}>Descripción</Label><Input id={`course-desc-${course.id}`} {...form.register('description')} /></div><div className="flex flex-col gap-1.5"><Label htmlFor={`course-prereq-${course.id}`}>Asignatura prerrequisito</Label><Input id={`course-prereq-${course.id}`} {...form.register('prerequisite')} placeholder="Ninguna / Licenciatura" /></div><div className="flex flex-col gap-1.5"><Label htmlFor={`course-facilitator-${course.id}`}>Facilitador/a</Label><Input id={`course-facilitator-${course.id}`} {...form.register('facilitator')} placeholder="Por asignar" /></div></div><fieldset className="rounded-xl border border-slate-200 p-3"><legend className="px-1 text-xs font-semibold text-slate-600">Carga académica (horas)</legend><div className="grid grid-cols-2 gap-3"><div className="flex flex-col gap-1"><Label htmlFor={`course-ht-${course.id}`} className="text-xs">HT</Label><Input id={`course-ht-${course.id}`} inputMode="numeric" {...form.register('hours_theoretical')} /></div><div className="flex flex-col gap-1"><Label htmlFor={`course-hp-${course.id}`} className="text-xs">HP</Label><Input id={`course-hp-${course.id}`} inputMode="numeric" {...form.register('hours_practical')} /></div><div className="flex flex-col gap-1"><Label htmlFor={`course-hiv-${course.id}`} className="text-xs">HIV</Label><Input id={`course-hiv-${course.id}`} inputMode="numeric" {...form.register('hours_research_virtual')} /></div><div className="flex flex-col gap-1"><Label htmlFor={`course-hi-${course.id}`} className="text-xs">HI</Label><Input id={`course-hi-${course.id}`} inputMode="numeric" {...form.register('hours_independent')} /></div></div></fieldset><div className="flex flex-wrap items-center justify-between gap-3"><select aria-label="Estado de la asignatura" {...form.register('status')} className="h-9 rounded-lg border border-slate-300 bg-white px-3 text-sm"><option value="pending">Pendiente</option><option value="in_progress">En curso</option><option value="review">En revisión</option><option value="completed">Completado</option></select><Button type="submit" size="sm" disabled={saving}><Save data-icon="inline-start" />{saving?'Guardando…':'Guardar'}</Button></div></form></CardContent></Card>
}

function ExperienceForm({participants,courses,onCreated}:{participants:Participant[];courses:Course[];onCreated:()=>void}){
 const form=useForm<z.infer<typeof experienceSchema>>({resolver:zodResolver(experienceSchema),defaultValues:{participant_id:'',course_id:'',title:'',description:'',learning_date:''}});const [busy,setBusy]=useState(false)
 return <Card className="border-blue-100 bg-white shadow-sm"><CardContent className="p-5"><h3 className="font-semibold text-[#0B2545]">Nueva experiencia</h3><form className="mt-4 grid gap-4 md:grid-cols-2" onSubmit={form.handleSubmit(async(values)=>{const parsed=experienceSchema.safeParse(values);if(!parsed.success)return;setBusy(true);const {error}=await supabase.from('portfolio_experiences').insert({...parsed.data,learning_date:parsed.data.learning_date||null,status:'draft'});if(error)toast.error('No se pudo registrar la experiencia.');else{toast.success('Experiencia guardada como borrador.');form.reset();onCreated()}setBusy(false)})}><div className="space-y-1.5"><Label htmlFor="exp-author">Participante</Label><select id="exp-author" {...form.register('participant_id')} className="h-10 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm"><option value="">Selecciona participante</option>{participants.map((p)=><option key={p.id} value={p.id}>{p.code} · {p.full_name||'Perfil pendiente'}</option>)}</select><FieldError>{form.formState.errors.participant_id?.message}</FieldError></div><div className="space-y-1.5"><Label htmlFor="exp-course">Asignatura</Label><select id="exp-course" {...form.register('course_id')} className="h-10 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm"><option value="">Selecciona asignatura</option>{courses.map((c)=><option key={c.id} value={c.id}>T{c.trimester} · {c.is_placeholder?'Título pendiente':c.title}</option>)}</select></div><div className="space-y-1.5"><Label htmlFor="exp-title">Título</Label><Input id="exp-title" {...form.register('title')} /><FieldError>{form.formState.errors.title?.message}</FieldError></div><div className="space-y-1.5"><Label htmlFor="exp-date">Fecha de aprendizaje</Label><Input id="exp-date" type="date" {...form.register('learning_date')} /></div><div className="space-y-1.5 md:col-span-2"><Label htmlFor="exp-desc">Descripción y aprendizajes</Label><textarea id="exp-desc" {...form.register('description')} className="min-h-24 w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm" /><FieldError>{form.formState.errors.description?.message}</FieldError></div><div className="md:col-span-2"><Button type="submit" disabled={busy}><Plus data-icon="inline-start" />{busy?'Guardando…':'Crear borrador'}</Button></div></form></CardContent></Card>
}

function ExperienceRow({experience,participant,course,evidence,onStatus,onDelete,onUpload}:{experience:Experience;participant?:Participant;course?:Course;evidence:Evidence[];onStatus:(status:Experience['status'])=>Promise<void>;onDelete:()=>void;onUpload:(file:File,title:string)=>Promise<void>}){
 const {mutate}=useSWRConfig()
 const [file,setFile]=useState<File|null>(null);const [title,setTitle]=useState('');const [signedUrls,setSignedUrls]=useState<Record<string,string>>({});const [busy,setBusy]=useState(false)
 async function getSignedUrl(item:Evidence){const {data,error}=await supabase.storage.from('portfolio-evidence').createSignedUrl(item.storage_path,600);if(error){toast.error('No se pudo generar el enlace seguro.');return}setSignedUrls((prev)=>({...prev,[item.id]:data.signedUrl}))}
 return <Card className="border-slate-200/80 shadow-sm"><CardContent className="p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><Badge variant="secondary">{STATUS_LABELS[experience.status]}</Badge><span className="text-xs text-slate-500">{participant?.code||'Participante'} · {course?.title||'Asignatura'}</span></div><h3 className="mt-3 font-semibold text-[#0B2545]">{experience.title}</h3><p className="mt-2 whitespace-pre-line text-sm leading-6 text-slate-600">{experience.description}</p></div><Button variant="ghost" size="icon" aria-label={`Eliminar ${experience.title}`} onClick={onDelete}><Trash2 className="text-red-700" /></Button></div><div className="mt-4 flex flex-wrap items-center gap-2"><label className="sr-only" htmlFor={`status-${experience.id}`}>Estado de publicación</label><select id={`status-${experience.id}`} value={experience.status} onChange={(event)=>void onStatus(event.target.value as Experience['status'])} className="h-9 rounded-lg border border-slate-300 bg-white px-3 text-sm"><option value="draft">Borrador</option><option value="review">En revisión</option><option value="published">Publicado</option></select>{experience.learning_date&&<span className="text-xs text-slate-500">{experience.learning_date}</span>}</div><div className="mt-4 rounded-xl bg-slate-50 p-4"><p className="text-sm font-medium text-slate-700">Evidencias ({evidence.length})</p><div className="mt-2 flex flex-wrap gap-2">{evidence.map((item)=><div key={item.id} className="flex items-center gap-2 rounded-lg bg-white px-3 py-2 text-sm"><span>{item.title} · {STATUS_LABELS[item.status]}</span>{signedUrls[item.id]?<a href={signedUrls[item.id]} target="_blank" rel="noreferrer" className="font-semibold text-blue-700">Abrir</a>:<button type="button" onClick={()=>void getSignedUrl(item)} className="font-semibold text-blue-700">Enlace seguro</button>}<button type="button" onClick={async()=>{const nextStatus=item.status==='published'?'draft':'published';const{error}=await supabase.from('portfolio_evidence').update({status:nextStatus}).eq('id',item.id);if(error)toast.error('No se pudo actualizar la evidencia.');else{toast.success(nextStatus==='published'?'Evidencia publicada.':'Evidencia retirada del sitio público.');void mutate('portfolio-admin-data')}}} className="text-xs font-semibold text-blue-700 hover:underline">{item.status==='published'?'Retirar':'Publicar'}</button><button type="button" aria-label={`Eliminar evidencia ${item.title}`} onClick={async()=>{if(!window.confirm(`¿Eliminar la evidencia «${item.title}»?`))return;const{error}=await supabase.from('portfolio_evidence').delete().eq('id',item.id);if(error){toast.error('No se pudo eliminar la evidencia.');return}const{error:storageError}=await supabase.storage.from('portfolio-evidence').remove([item.storage_path]);if(storageError)toast.error('Se eliminó el registro, pero no el archivo adjunto.');else toast.success('Evidencia eliminada.');void mutate('portfolio-admin-data')}} className="text-xs font-semibold text-red-700 hover:underline">Eliminar</button></div>)}</div><div className="mt-3 flex flex-wrap items-end gap-2"><div className="min-w-48 flex-1"><Label htmlFor={`file-title-${experience.id}`} className="text-xs">Nombre de la evidencia</Label><Input id={`file-title-${experience.id}`} value={title} onChange={(e)=>setTitle(e.target.value)} placeholder="Ej. Planificación didáctica" className="mt-1 bg-white" /></div><div className="min-w-48 flex-1"><Label htmlFor={`file-${experience.id}`} className="text-xs">Archivo · máx. 10 MB</Label><Input id={`file-${experience.id}`} type="file" accept="image/jpeg,image/png,image/webp,application/pdf,.docx,.pptx,.xlsx" onChange={(e)=>setFile(e.target.files?.[0]||null)} className="mt-1 bg-white" /></div><Button size="sm" disabled={!file||busy} onClick={async()=>{if(!file)return;setBusy(true);await onUpload(file,title.trim()||file.name);setFile(null);setTitle('');setBusy(false)}}><Upload data-icon="inline-start" />{busy?'Subiendo…':'Adjuntar'}</Button></div></div></CardContent></Card>
}

function ReflectionForm({participants,courses,onCreated}:{participants:Participant[];courses:Course[];onCreated:()=>void}){
 const form=useForm<z.infer<typeof reflectionSchema>>({resolver:zodResolver(reflectionSchema),defaultValues:{participant_id:'',course_id:'',title:'',body:'',reflection_type:'individual'}});const[busy,setBusy]=useState(false)
 return <Card className="border-blue-100 bg-white shadow-sm"><CardContent className="p-5"><h3 className="font-semibold text-[#0B2545]">Nueva reflexión</h3><form className="mt-4 grid gap-4 md:grid-cols-2" onSubmit={form.handleSubmit(async(values)=>{setBusy(true);const parsed=reflectionSchema.safeParse(values);if(!parsed.success){setBusy(false);return}const {data:saved,error}=await supabase.from('portfolio_reflections').insert({...parsed.data,course_id:parsed.data.course_id||null,status:'draft'}).select('id').single();if(error||!saved){await logAdminAction('create_reflection','portfolio_reflections',undefined,{},'failure');toast.error('No se pudo crear la reflexión.')}else{if(!await logAdminAction('create_reflection','portfolio_reflections',saved.id))toast.warning('La reflexión se creó, pero no se pudo registrar la auditoría.');toast.success('Reflexión creada como borrador.');form.reset();onCreated()}setBusy(false)})}><div className="space-y-1.5"><Label htmlFor="reflection-author">Participante responsable</Label><select id="reflection-author" {...form.register('participant_id')} className="h-10 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm"><option value="">Selecciona participante</option>{participants.map((p)=><option key={p.id} value={p.id}>{p.code} · {p.full_name||'Perfil pendiente'}</option>)}</select></div><div className="space-y-1.5"><Label htmlFor="reflection-type">Tipo</Label><select id="reflection-type" {...form.register('reflection_type')} className="h-10 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm"><option value="individual">Individual</option><option value="group">Grupal</option></select></div><div className="space-y-1.5"><Label htmlFor="reflection-course">Asignatura (opcional)</Label><select id="reflection-course" {...form.register('course_id')} className="h-10 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm"><option value="">General / final</option>{courses.map((c)=><option key={c.id} value={c.id}>T{c.trimester} · {c.is_placeholder?'Título pendiente':c.title}</option>)}</select></div><div className="space-y-1.5"><Label htmlFor="reflection-title">Título</Label><Input id="reflection-title" {...form.register('title')} /></div><div className="space-y-1.5 md:col-span-2"><Label htmlFor="reflection-body">Reflexión</Label><textarea id="reflection-body" {...form.register('body')} className="min-h-32 w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm" /></div><div className="md:col-span-2"><Button type="submit" disabled={busy}><Plus data-icon="inline-start" />{busy?'Guardando…':'Crear reflexión'}</Button></div></form></CardContent></Card>
}

function ReflectionRow({reflection,participant,course,onStatus,onDelete}:{reflection:Reflection;participant?:Participant;course?:Course;onStatus:(status:Reflection['status'])=>Promise<void>;onDelete:()=>void}){
 return <Card className="border-slate-200/80 shadow-sm"><CardContent className="p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><div className="flex flex-wrap items-center gap-2"><Badge variant={reflection.reflection_type==='group'?'default':'secondary'}>{reflection.reflection_type==='group'?'Grupal':'Individual'}</Badge><span className="text-xs text-slate-500">{participant?.full_name||participant?.code} {course?`· ${course.title}`:''}</span></div><h3 className="mt-3 font-semibold text-[#0B2545]">{reflection.title}</h3></div><Button variant="ghost" size="icon" aria-label={`Eliminar ${reflection.title}`} onClick={onDelete}><Trash2 className="text-red-700" /></Button></div><p className="mt-3 whitespace-pre-line text-sm leading-6 text-slate-600">{reflection.body}</p><div className="mt-4"><label className="sr-only" htmlFor={`reflection-status-${reflection.id}`}>Estado de reflexión</label><select id={`reflection-status-${reflection.id}`} value={reflection.status} onChange={(event)=>void onStatus(event.target.value as Reflection['status'])} className="h-9 rounded-lg border border-slate-300 bg-white px-3 text-sm"><option value="draft">Borrador</option><option value="review">En revisión</option><option value="published">Publicado</option></select></div></CardContent></Card>
}

function SettingsEditor({settings,onSave}:{settings:Array<{key:string;value:Record<string,string>}>;onSave:(value:Record<string,string>)=>Promise<void>}){
 const current=settings.find((item)=>item.key==='institution')?.value||{};const[values,setValues]=useState({institution:current.institution||'Universidad Abierta Para Adultos (UAPA)',decree:current.decree||'',program:current.program||'Especialidad en Habilitación Docente en Informática',modality:current.modality||'Virtual',cohort:current.cohort||'',duration:current.duration||'',general_data:current.general_data||'',title:current.title||'Portafolio Académico Digital',public_intro:current.public_intro||'',pensum_year:current.pensum_year||'2024'});const[saving,setSaving]=useState(false)
 const fields=[{id:'institution',label:'Institución'},{id:'decree',label:'Decreto o resolución'},{id:'program',label:'Programa'},{id:'modality',label:'Modalidad'},{id:'cohort',label:'Cohorte'},{id:'duration',label:'Duración'},{id:'title',label:'Título del portafolio'},{id:'pensum_year',label:'Año del pénsum'}] as const
 return <Card className="border-slate-200/80 shadow-sm"><CardContent className="p-6"><div className="flex items-center gap-3"><Settings2 className="text-blue-700" /><div><h3 className="font-semibold text-[#0B2545]">Identidad y datos generales</h3><p className="text-sm text-slate-500">Información institucional persistida y utilizada por el portafolio.</p></div></div><div className="mt-5 grid gap-4 md:grid-cols-2">{fields.map(({id,label})=><div key={id} className="flex flex-col gap-1.5"><Label htmlFor={`institution-${id}`}>{label}</Label><Input id={`institution-${id}`} maxLength={180} value={values[id]} onChange={(e)=>setValues({...values,[id]:e.target.value})} /></div>)}<div className="flex flex-col gap-1.5 md:col-span-2"><Label htmlFor="institution-intro">Descripción introductoria</Label><textarea id="institution-intro" maxLength={2000} value={values.public_intro} onChange={(e)=>setValues({...values,public_intro:e.target.value})} className="min-h-20 w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm" /></div><div className="flex flex-col gap-1.5 md:col-span-2"><Label htmlFor="institution-general-data">Datos generales</Label><textarea id="institution-general-data" maxLength={4000} value={values.general_data} onChange={(e)=>setValues({...values,general_data:e.target.value})} placeholder="Información adicional del programa o de la cohorte" className="min-h-24 w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm" /></div></div><Button className="mt-5" disabled={saving} onClick={async()=>{setSaving(true);try{await onSave(values)}finally{setSaving(false)}}}><Save data-icon="inline-start" />{saving?'Guardando…':'Guardar datos generales'}</Button></CardContent></Card>
}

function BackupPanel({data,onRestored}:{data:NonNullable<ReturnType<typeof useDashboardData>>;onRestored:()=>void}){
 const [busy,setBusy]=useState(false)
 const [pending,setPending]=useState<{fileName:string;data:Record<string,unknown[]>}|null>(null)
 const backupKeys=['participants','courses','experiences','experienceParticipants','evidence','reflections','academicReflections','settings'] as const
 type BackupData=Record<(typeof backupKeys)[number],unknown[]>
 function downloadUrl(content:string,fileName:string){const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=fileName;anchor.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000)}
 async function downloadBackup(){setBusy(true);try{const [academicResult,relationsResult]=await Promise.all([supabase.from('portfolio_academic_reflections').select('*'),supabase.from('portfolio_experience_participants').select('experience_id,participant_id')]);if(academicResult.error||relationsResult.error)throw new Error('No se pudieron incluir las reflexiones o relaciones en el respaldo.');const backup={schemaVersion:2,createdAt:new Date().toISOString(),data:{participants:data.participants,courses:data.courses,experiences:data.experiences,evidence:data.evidence,experienceParticipants:relationsResult.data||[],reflections:data.reflections,academicReflections:academicResult.data||[],settings:data.settings}};const fileName=`portafolio-uapa-respaldo-${new Date().toISOString().slice(0,10)}.json`;downloadUrl(JSON.stringify(backup,null,2),fileName);if(!await logAdminAction('export_backup','backup',fileName,{schemaVersion:2}))toast.warning('El respaldo se descargó, pero no se pudo registrar la auditoría.');toast.success('Respaldo completo descargado. Incluye datos personales; consérvalo en un lugar privado.')}catch(error){await logAdminAction('export_backup','backup',undefined,{message:error instanceof Error?error.message:'unknown'},'failure');toast.error(error instanceof Error?error.message:'No se pudo preparar el respaldo.')}finally{setBusy(false)}}
 async function inspectBackup(file:File){setBusy(true);try{if(file.size>20*1024*1024)throw new Error('El archivo supera el límite de 20 MB.');const parsed=JSON.parse(await file.text());const raw=parsed?.data;if(![1,2].includes(parsed?.schemaVersion)||!raw||!['participants','courses','experiences','evidence','reflections','settings'].every((key)=>Array.isArray(raw[key])))throw new Error('Formato inválido: faltan secciones requeridas o la versión no es compatible.');const values:BackupData={participants:raw.participants,courses:raw.courses,experiences:raw.experiences,evidence:raw.evidence,experienceParticipants:Array.isArray(raw.experienceParticipants)?raw.experienceParticipants:[],reflections:raw.reflections,academicReflections:Array.isArray(raw.academicReflections)?raw.academicReflections:[],settings:raw.settings};if(Object.values(values).some((items)=>items.some((item)=>!item||typeof item!=='object'||Array.isArray(item))))throw new Error('El respaldo contiene registros con estructura incorrecta.');setPending({fileName:file.name,data:values})}catch(error){toast.error(error instanceof Error?error.message:'No se pudo validar el archivo.')}finally{setBusy(false)}}
 function uniqueBy<T extends Record<string,unknown>>(records:T[],key:(item:T)=>string){const seen=new Set<string>();return records.filter((record)=>{const value=key(record);if(!value||seen.has(value))return false;seen.add(value);return true})}
 async function importBackup(){if(!pending)return;setBusy(true);try{const source=pending.data;const unique=(key:string)=>uniqueBy((source[key]||[]) as Array<Record<string,unknown>>,(item)=>String(item.id||item.key||''));const experiences=unique('experiences').map(({participants:_participants,...experience})=>experience);const experienceParticipants=uniqueBy((source.experienceParticipants||[]) as Array<Record<string,unknown>>,(item)=>`${item.experience_id}:${item.participant_id}`);const operations=[['portfolio_participants',unique('participants')],['portfolio_courses',unique('courses')],['portfolio_experiences',experiences],['portfolio_evidence',unique('evidence')],['portfolio_reflections',unique('reflections')],['portfolio_academic_reflections',unique('academicReflections')],['portfolio_settings',unique('settings')]] as const;for(const [table,rows] of operations){if(!rows.length)continue;const {error}=await supabase.from(table).upsert(rows as never[]);if(error)throw new Error(`No se pudieron importar ${table}. Comprueba que el respaldo corresponde a esta versión.`)}if(experienceParticipants.length){const {error}=await supabase.from('portfolio_experience_participants').upsert(experienceParticipants as never[]);if(error)throw new Error('No se pudieron restaurar los participantes de las experiencias.')}if(!await logAdminAction('import_backup','backup',pending.fileName,{counts:Object.fromEntries(backupKeys.map((key)=>[key,source[key]?.length||0]))}))toast.warning('La importación terminó, pero no se pudo registrar la auditoría.');toast.success('Importación completada. Los registros con el mismo identificador se actualizaron; los demás se añadieron.');setPending(null);onRestored()}catch(error){await logAdminAction('import_backup','backup',pending.fileName,{message:error instanceof Error?error.message:'unknown'},'failure');toast.error(error instanceof Error?error.message:'No se pudo importar el respaldo.')}finally{setBusy(false)}}
 async function restoreTemplate(){const confirmed=window.confirm('Se reemplazarán únicamente los datos de identidad institucional (institución, decreto, programa, modalidad, cohorte, duración, descripción y año del pénsum) por la plantilla inicial. Participantes P1–P6, asignaturas, experiencias, evidencias y reflexiones no se modificarán. ¿Deseas continuar?');if(!confirmed)return;setBusy(true);try{const defaults={institution:'Universidad Abierta Para Adultos (UAPA)',decree:'',program:'Especialidad en Habilitación Docente en Informática',modality:'Virtual',cohort:'',duration:'',general_data:'',title:'Portafolio Académico Digital',public_intro:'',pensum_year:'2024'};const {error}=await supabase.from('portfolio_settings').upsert({key:'institution',value:defaults});if(error)throw error;if(!await logAdminAction('restore_initial_template','institution_settings',undefined,{replacedFields:Object.keys(defaults)}))toast.warning('La plantilla se restauró, pero no se pudo registrar la auditoría.');toast.success('Plantilla institucional inicial restaurada. El resto del contenido se conservó.');onRestored()}catch(error){await logAdminAction('restore_initial_template','institution_settings',undefined,{message:error instanceof Error?error.message:'unknown'},'failure');toast.error('No se pudo restaurar la plantilla inicial.')}finally{setBusy(false)}}
 const previewCounts=pending?backupKeys.map((key)=>({key,label:key==='experienceParticipants'?'Relaciones de experiencias':key==='academicReflections'?'Reflexiones finales P1–P6':key==='settings'?'Información institucional':key==='participants'?'Participantes':key==='courses'?'Asignaturas':key==='experiences'?'Experiencias':key==='evidence'?'Evidencias':'Reflexiones',count:pending.data[key]?.length||0})):[]
 return <div className="flex flex-col gap-5"><Card className="border-slate-200/80 shadow-sm"><CardContent className="p-6"><h3 className="font-semibold text-[#0B2545]">Respaldo y restauración</h3><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">Exporta e importa información institucional, P1–P6, asignaturas, experiencias y sus participantes, evidencias con metadatos, reflexiones y ajustes del sitio. La restauración combina por identificador y no elimina registros. Los archivos contienen información personal: guárdalos de forma privada.</p><div className="mt-5 flex flex-wrap gap-3"><Button disabled={busy} onClick={()=>void downloadBackup()}><Download data-icon="inline-start" />{busy?'Procesando…':'Descargar respaldo JSON'}</Button><label className="inline-flex h-9 cursor-pointer items-center gap-2 rounded-lg border border-slate-300 bg-white px-3 text-sm font-medium hover:bg-slate-50"><Upload size={16} />{busy?'Validando…':'Seleccionar JSON'}<input className="sr-only" type="file" accept="application/json,.json" disabled={busy} onChange={(event)=>{const file=event.target.files?.[0];if(file)void inspectBackup(file);event.currentTarget.value=''}} /></label></div>{pending&&<div className="mt-5 rounded-xl border border-blue-100 bg-blue-50/60 p-4"><h4 className="font-semibold text-[#0B2545]">Revisar antes de importar: {pending.fileName}</h4><p className="mt-1 text-sm text-slate-600">Se validó la estructura. Los elementos con el mismo identificador se actualizarán; no se eliminarán datos.</p><ul className="mt-3 grid gap-2 text-sm sm:grid-cols-2">{previewCounts.map((item)=><li key={item.key} className="flex justify-between rounded-lg bg-white px-3 py-2"><span>{item.label}</span><strong>{item.count}</strong></li>)}</ul><div className="mt-4 flex gap-2"><Button disabled={busy} onClick={()=>void importBackup()}>{busy?'Importando…':'Confirmar e importar'}</Button><Button variant="outline" disabled={busy} onClick={()=>setPending(null)}>Cancelar</Button></div></div>}</CardContent></Card><Card className="border-amber-200 bg-amber-50/50 shadow-sm"><CardContent className="p-6"><h3 className="font-semibold text-[#0B2545]">Restaurar plantilla inicial</h3><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">Restablece solo los campos de identidad institucional a los valores iniciales. No modifica participantes, asignaturas, experiencias, evidencias ni reflexiones.</p><Button className="mt-4" variant="outline" disabled={busy} onClick={()=>void restoreTemplate()}><Archive data-icon="inline-start" />Restaurar plantilla inicial</Button></CardContent></Card></div>
}

function EmptyCard({text}:{text:string}){return <Card className="border-dashed bg-white"><CardContent className="p-8 text-center text-sm text-slate-500">{text}</CardContent></Card>}
function useDashboardData(){return {participants:[] as Participant[],courses:[] as Course[],experiences:[] as Experience[],evidence:[] as Evidence[],reflections:[] as Reflection[],settings:[] as Array<{key:string;value:Record<string,string>}>}}
